  "explanations": [
    {
      "topic": {
        "text": "Reference types in Java store a reference (address) to an object in memory rather than the actual object value.",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "When a reference type variable (e.g., a variable of a class type) is declared, the variable holds the address of the object in memory. The actual object resides elsewhere in the heap, and the variable points to that location.",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Primitive types in Java store the actual value directly in the variable's memory location.",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "When a primitive variable (e.g., a byte) is declared, the value assigned to it is stored directly in the memory location associated with that variable.",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Assigning one reference variable to another copies the reference, not the object.",
        "refs": ["Q0002"]
      },
      "explanation_text": {
        "text": "When `point2 = point1;` is executed, the value copied is the address of the `Point` object, so both `point1` and `point2` refer to the same object in memory.",
        "refs": ["Q0002"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "Modifying an object through one reference variable affects all other references to the same object.",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_text": {
        "text": "Changing a field (e.g., `point1.x = 2;`) updates the single underlying object. Since `point2` references the same object, reading `point2.x` will reflect the updated value.",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_type": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "Demonstration of two reference variables pointing to the same `Point` object and showing that a change via one variable is visible through the other.",
        "refs": ["Q0003", "Q0004"]
      },
      "example_text": {
        "text": "```java\nPoint point1 = new Point(1, 1);\nPoint point2 = point1; // point2 references the same object\npoint1.x = 2; // modify via point1\nSystem.out.println(point2.x); // prints 2, showing the change is visible\n```",
        "refs": ["Q0003", "Q0004"]
      },
      "example_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "Reference types are copied by reference (address), while primitive types are copied by value.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Two reference variables that are assigned to the same object are not independent; they share the same underlying object.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    }
  ],
